   "jagdlich": "Goldschakal ist weder in § 2 BJagdG (https://www.gesetze-im-internet.de/bjagdg/__2.html) noch in § 1 der SH-VO aufgeführt. Die Entnahme eines Goldschakals auf Sylt 2025 erfolgte nur per Ausnahmegenehmigung des Landesamts für Umwelt (https://ljv-sh.de/goldschakal-auf-sylt-ausnahmegenehmigung-zur-entnahme-erteilt/).",
