   "jagdlich": "SH: Nonnengänse 1. Oktober bis 28. Februar nur zur Vergrämung außerhalb europäischer Vogelschutzgebiete und nur zur Schadensabwehr auf gefährdeten Acker- und Grünlandkulturen (Sachverständigen-Feststellung bzw. Dokumentation erforderlich) – JagdZV SH 2019 i. d. F. vom 16.07.2024 (https://www.gesetze-rechtsprechung.sh.juris.de/bssh/document/jlr-NNLSH00002D41); siehe auch https://ljv-sh.de/jagdzeiten-neue-landesverordnung-erweitert-jagdzeiten/",
